function encounter(id){const e=eventID(id);if(!e||!Road.ready(e,state))return;if(!e.repeatable&&(state.counts[id]||0)>0){toast('The way is already open.');return;}if(!state.learned.length){toast('Discover and keep a way-card first.');return;}g.battle={event:e,hand:Road.drawHand(state),round:0,card:null,matched:false,connection:'',done:false};battleView();/* Code by Daniel using ChatGPT — October 11, 2026 */}
function battleView(){const e=g.battle.event;show(`<h2 id="panel-title">${esc(e.title.split(' · ').slice(1).join(' · ')||e.title)}</h2>${enemyHTML(e)}${eventScripture(e)}<p>${story(e.description,null,e)}</p><details><summary>Look for a connection</summary><p class="hint">${story(e.sections.hint,null,e)}</p></details><h3>Your encounter hand</h3><p class="hint">Four random discoveries, without replacement. With fewer than four discoveries, all are drawn. This hand stays the same if you retry.</p><div class="cards">${g.battle.hand.map(function b(id){return buttonCard(byID(id),'battle-card');/* Code by Daniel using ChatGPT — October 11, 2026 */}).join('')}</div><div class="actions"><button data-action="close">Withdraw for now</button></div>`,'battle','ENCOUNTER · '+(e.rounds||1)+' RECALL'+((e.rounds||1)>1?'S':''));/* Code by Daniel using ChatGPT — October 11, 2026 */}
function battleCard(id){const b=g.battle,c=byID(id);if(!b||!b.hand.includes(id))return;const matches=Road.match(c,b.event);b.card=id;b.matched=matches.length>0;show(`<h2 id="panel-title">${rich(c.summary)}</h2><p class="eyebrow">${esc(c.title)} · ${esc(c.translation)}</p><details><summary>Read the whole card before recall</summary><blockquote class="verse">${rich(c.text)}</blockquote></details><p class="${b.matched?'feedback':'feedback warn'}">${b.matched?'Connection found: '+esc(matches.join(' · '))+'.':'No configured keyword matches this card.'}</p><label class="reply" for="reply">Your reply or connection · optional, your own words</label><textarea id="reply" maxlength="1000" placeholder="I am a Riverkin. My hope is in God, who gives us breath…">${esc(b.connection||state.reply)}</textarea><p class="hint">The game does not grade or send these words. ${!b.matched&&state.settings.allowConnection?'If you see a real connection, explain it and use your judgment to carry this card.':''}</p><div class="actions">${b.matched?'<button class="primary" data-action="begin-battle">Recall & unlock the move</button>':state.settings.allowConnection?'<button class="primary" data-action="self-connect">Use my explained connection</button>':''}<button data-action="battle-back">Choose another card</button><button data-action="close">Withdraw</button></div>`,'battle-card','A PASSAGE · A RESPONSE');/* Code by Daniel using ChatGPT — October 11, 2026 */}
function beginBattle(self=false){if(!g.battle)return;const reply=$('#reply')?.value||'';if(self&&reply.trim().length<12){toast('Write a short connection first, or choose a matching card.');return;}g.battle.connection=reply;state.reply=reply;if(self)g.battle.matched=true;persist();practice(g.battle.card);/* Code by Daniel using ChatGPT — October 11, 2026 */}
function win(){const b=g.battle;if(!b||b.done||b.round<(b.event.rounds||1)||!b.matched)return;b.done=true;const e=b.event,c=byID(b.card),first=!(state.counts[e.id]>0),outcome=story(e.sections.success,c,e);state.counts[e.id]=(state.counts[e.id]||0)+1;for(const f of e.grants||[])if(!state.flags.includes(f))state.flags.push(f);if(first&&e.item&&!state.items.includes(e.item))state.items.push(e.item);if(e.consume)state.items=state.items.filter(function keep(i){return i!==e.consume;/* Code by Daniel using ChatGPT — October 11, 2026 */});state.xp+=Math.max(0,Math.min(200,Number(e.reward)||15));state.hearts=Math.min(5,state.hearts+1);persist();hud();g.burst={x:state.player.x,y:state.player.y,start:g.clock,move:e.move};show(`<h2 id="panel-title">${esc(e.move)}!</h2>${enemyHTML(e)}${eventScripture(e)}<p>${outcome}</p>${b.connection?'<p class="caption">Your reply: “'+esc(b.connection)+'”</p>':''}<p class="hint">+'+(Number(e.reward)||15)+' trail XP · your passage stays in the way-pack.</p><button class="primary" data-action="close">Back into the adventure</button>`,'outcome','THE WAY OPENS');/* Code by Daniel using ChatGPT — October 11, 2026 */}
function risk(){const b=g.battle;if(!b)return;state.hearts=Math.max(0,state.hearts-(Number(b.event.hearts)||0));const fallen=state.hearts===0;if(fallen){state.hearts=5;state.player={x:regionConfig().spawn[0],y:regionConfig().spawn[1]};Opening.reset(state.region,state.player);g.camera=Exploration.camera(state.player,viewZoom(),state.settings.camera,canvas.width/canvas.height);}persist();hud();show(`<h2 id="panel-title">A stumble on the road</h2><p>${story(b.event.sections.failure,byID(b.card),b.event)}</p>${fallen?'<p>You return to camp and recover your hearts. Your cards and quest progress are kept.</p>':''}<div class="actions"><button class="primary" data-action="retry-battle">Return to the words</button><button data-action="close">Regroup in the woods</button></div>`,'failure');/* Code by Daniel using ChatGPT — October 11, 2026 */}
function visit(id){if(Leaf.visit(id)||Adventure.visit(id))return;const e=eventID(id);if(!e)return;if(id==='reedbank-bed'){const bed=OPENING_WORLD.regions[state.region]?.bed;if(bed)Life.enterBed(bed,state.player);return;}if(!Road.ready(e,state)){toast('This place is not ready: '+(e.requires||[]).join(', ')+(e.min_cards?' · discover '+e.min_cards+' cards':''));return;}if(e.kind==='npc'){const content=state.settings.dialogue==='short'?story(e.sections.short||shortDialogue(e),null,e):story(e.description,null,e)+'</p><p>'+story(e.sections.success,null,e);if(e.optional_drama&&!state.counts[id]){state.counts[id]=1;for(const f of e.grants||[])if(!state.flags.includes(f))state.flags.push(f);persist();}show(`<h2 id="panel-title">${esc(e.title.split(' · ').pop())}</h2>${enemyHTML(e)}${eventScripture(e)}<p>${content}</p><div class="actions"><button data-action="dialogue-length" data-id="${e.id}">${state.settings.dialogue==='short'?'Know more':'Less text'}</button><button class="primary" data-action="close">Continue exploring</button></div>`,'npc','A FELLOW TRAVELER');return;}if(e.kind==='camp'){camp();return;}if(e.kind==='encounter'){encounter(id);return;}if(e.kind==='portal'){if(!REGIONS[e.target?.region]){toast('The road beyond is not open yet.');return;}if(!enterRegion(e.target.region,e.target.point,false,e.target.facing||g.direction))return;show(`<h2 id="panel-title">${esc(e.title)}</h2><p>${story(e.description,null,e)}</p><p>${story(e.sections.success,null,e)}</p><button class="primary" data-action="close">Continue the journey</button>`,'portal');return;}for(const f of e.grants||[])if(!state.flags.includes(f))state.flags.push(f);if(e.item&&!state.items.includes(e.item))state.items.push(e.item);persist();hud();show(`<h2 id="panel-title">${esc(e.title)}</h2><p>${story(e.description,null,e)}</p><p>${story(e.sections.success,null,e)}</p><div class="actions">${e.target&&REGIONS[e.target.region]?`<button class="primary" data-action="region" data-region="${esc(e.target.region)}" data-id="${e.id}">Walk into ${esc(REGIONS[e.target.region].name)}</button>`:''}<button data-action="close">Keep exploring ${esc(regionConfig().name)}</button><button data-action="camp">Return to practice</button></div>`,'finish');/* Code by Daniel using ChatGPT — October 11, 2026 */}
function visiblePlaces(){const result=[],open=bridgeOpen();for(const entry of [...cards,...events]){const kind=cards.includes(entry)?'card':'event',discovery=kind==='card'&&scriptureMD===DEFAULT_SCRIPTURE?OPENING_WORLD.discovery?.[entry.id]:null;if(discovery&&discovery.region!==state.region)continue;if(kind==='card'&&state.learned.includes(entry.id))continue;if(kind==='event'&&(!entry.repeatable&&state.counts[entry.id]>0||entry.optional_drama&&!state.settings.drama||entry.hide_locked&&!Road.ready(entry,state)||(entry.exclude_flags||[]).some(function excluded(f){return state.flags.includes(f);/* Code by Daniel using ChatGPT — October 11, 2026 */})))continue;const key=state.region+'|'+open+'|'+entry.id;let p=g.positionCache.get(key);if(p===undefined){const placement=discovery?.point||Leaf.home(entry)||OPENING_WORLD.regions[state.region]?.placements[entry.id];const source=placement?{x:placement[0],y:placement[1]}:Road.position(entry,state.seed,state.region);p=source?{...source,...Exploration.safe(source,terrain,open)}:null;g.positionCache.set(key,p);}if(!p)continue;if(kind==='card'){if(Leaf.discovery(entry,p))result.push({kind,entry,...p,drawDepth:Leaf.cardDepth(entry,p.y)});continue;}const actorKey=state.region+'|'+entry.id;if(!g.actors.has(actorKey))g.actors.set(actorKey,Exploration.actor(entry,p));const actor=g.actors.get(actorKey);result.push({kind,entry,...p,x:actor.x,y:actor.y,actor});}return result;/* Code by Daniel using ChatGPT — October 11, 2026 */}
function canReach(place){return state.region!=='greenwood'||place.y>=58||bridgeOpen();/* Code by Daniel using ChatGPT — October 11, 2026 */}
function journeyGuide(){if(Opening.enabled(state.region))return '<p class="hint"><strong>The road onward:</strong> '+esc(openingObjective()||'Explore the highroad.')+'</p><p class="hint">Reedbank → Woodland Road → Whiteledge → Carverbough → Greenwood. Building doorways lead to their own rooms. Return through the same door. Your discoveries travel with you.</p>';const f=state.flags;let next=state.region==='greenwood'?!f.includes('bridge-open')?'Keep at least one way-card near camp, then follow the road northeast to the bridge. Interact with the squirrel at the southern end and complete a recall.':!f.includes('ghouls-won')?'Cross the bridge northward. Gather at least three way-cards, then follow the north-bank road east to the Man-Ghouls.':!f.includes('warden-won')?'Follow the northern road northeast to the watch-ring. Defeat its guardian with two recalls.':'Continue east from the watch-ring to the arch in the northeastern corner. Interact, then choose Walk into Silvermere. The eastern arch, “A Road Beyond the Trees,” is available below.':state.region==='silvermere'?'Follow Silvermere’s eastern road to Birchwater Boughs. The mentoring story is optional.':state.region==='birchwater'?'The eastern road leads to Lilyfall Court. Return west to Silvermere whenever you wish.':state.region==='lilyfall'&&!f.includes('outer-road-open')?'Find the broken trail marker on the eastern side of Lilyfall Court. Restore it with two recalls to open the outer road.':'Continue east to the next region, or explore the return roads and tunnels.';return `<p class="hint"><strong>The road onward:</strong> ${esc(next)}</p><details><summary>Journey through all six regions</summary><p>Greenwood → Silvermere → Birchwater Boughs → Lilyfall Court → Alderwatch March → Highfold Reach.</p><p>In Greenwood: discover cards, release the bridge, face the Man-Ghouls, restore the watch-ring, then interact with the northeastern arch and choose Walk into Silvermere. You need three discoveries for the watch-ring. In Lilyfall, restore the eastern trail marker to open the last two regions. Side stories, bears, and optional encounters are not required to travel.</p><p>This is an open-ended journey: return to camp to practice or find further cards after Greenwood’s quest. Places also offers direct travel to places you have seen, plus the eastern arch once its guardian is defeated.</p></details>`;/* Code by Daniel using ChatGPT — October 11, 2026 */}
function mapPanel(){const places=visiblePlaces().filter(function known(p){return state.knownPlaces.includes(p.entry.id)||p.entry.id==='camp'||(state.region==='greenwood'&&p.entry.id==='east-road'&&state.flags.includes('warden-won'));/* Code by Daniel using ChatGPT — October 11, 2026 */});show(`<h2 id="panel-title">Places you have explored</h2>${journeyGuide()}<p>The woods beyond this view still hold their secrets. This list remembers places you have seen; use it for direct travel if you wish.</p><p class="hint">${(state.regionVisited[state.region]||state.visited).length} views explored · zoom ${state.settings.zoom}× · about ${Math.round(viewZoom()**2)} screen areas across ${esc(regionConfig().name)}.</p><div class="places">${places.map(function place(p){const ready=Road.ready(p.entry,state)&&canReach(p);return `<button data-action="travel" data-id="${p.entry.id}" data-kind="${p.kind}" ${ready?'':'disabled'}>${p.kind==='card'?'✦ Way-card · ':''}${esc(p.entry.title)}<small class="hint"> · ${ready?'Explore':'Locked'}</small></button>`;/* Code by Daniel using ChatGPT — October 11, 2026 */}).join('')}</div><div class="actions"><button data-action="close">Return to the woods</button></div>`,'map');/* Code by Daniel using ChatGPT — October 11, 2026 */}
function travel(id,kind){const entry=kind==='card'?byID(id):eventID(id),place=visiblePlaces().find(function same(p){return p.entry.id===id&&p.kind===kind;/* Code by Daniel using ChatGPT — October 11, 2026 */});if(!entry||!place||!Road.ready(entry,state)||!canReach(place))return;state.player=Exploration.safe(place,terrain,bridgeOpen());Opening.reset(state.region,state.player);g.camera=Exploration.camera(state.player,viewZoom(),state.settings.camera,canvas.width/canvas.height);persist();if(kind==='card')read(id,true);else visit(id);/* Code by Daniel using ChatGPT — October 11, 2026 */}
function settings(){show(`<h2 id="panel-title">Your way through the woodland roads</h2><div class="actions"><button class="primary" data-action="opening-return">Visit Reedbank home</button><button data-action="find-footing">Find clear footing</button></div><p class="hint">Visit the new opening while keeping your discoveries, settings, and imported Markdown.</p><div class="setting-grid"><div><label for="mode">Recall controls</label><select id="mode"><option value="phrases">Select phrases</option><option value="choose">Multiple choice</option><option value="type">Type the missing half</option></select></div><div><label for="scope">What to practice</label><select id="scope"><option value="summary">Card headlines · relaxed</option><option value="excerpts">Successive card excerpts · deeper</option></select></div><div><label for="avatar">Riverkin</label><select id="avatar"><option value="boy">Boy</option><option value="girl">Girl</option></select></div><div><label for="camera">Exploration view</label><select id="camera"><option value="follow">Follow the traveler · centered</option><option value="screens">Classic screen transitions</option></select></div><div><label for="zoom">View zoom</label><select id="zoom"><option value="3">3× · wider</option><option value="4.25">4.25× · about 18 screen areas</option><option value="5">5× · closer</option></select></div><div><label for="difficulty">Recall difficulty</label><select id="difficulty"><option value="easy">Easier · phrase groups</option><option value="hard">Harder · eight or more choices</option></select></div><div><label for="dialogue">NPC dialogue</label><select id="dialogue"><option value="full">Full text</option><option value="short">Less text</option></select></div><div><label for="pad">Controller mapping</label><select id="pad"><option value="standard">Standard / F310 in X mode</option><option value="f310-direct">F310 DirectInput fallback</option></select></div></div><label class="check"><input type="checkbox" id="music" ${state.settings.music?'checked':''}>Forest music · quiet instrumental</label><label for="musicVolume">Music volume · ${Math.round(state.settings.musicVolume*100)}%</label><input type="range" id="musicVolume" min="0" max="100" value="${Math.round(state.settings.musicVolume*100)}"><label class="check"><input type="checkbox" id="drama" ${state.settings.drama?'checked':''}>Optional Silvermere story · mentoring, pride & reconciliation</label><label for="idleMinutes">Rest after inactivity</label><select id="idleMinutes"><option value="2">2 minutes</option><option value="5">5 minutes</option><option value="10">10 minutes</option></select><p class="hint">Controller, keyboard, and touch activity keep the game awake where the browser supports it. If audio needs permission, click ♫ Enable once.</p><label class="check"><input type="checkbox" id="motion" ${state.settings.motion?'checked':''}>Gentle motion and move effects</label><label class="check"><input type="checkbox" id="speech" ${state.settings.speech?'checked':''}>Ambient speech bubbles · use Interact for conversations</label><label class="check"><input type="checkbox" id="allowConnection" ${state.settings.allowConnection?'checked':''}>Allow a player-explained connection when tags do not match</label><label class="check"><input type="checkbox" id="terrainDebug" ${g.terrainDebug?'checked':''}>Show scene geometry · walls, walk surfaces, doors & roof groups · F2</label><details><summary>Keyboard, touch & Logitech F310</summary><p class="hint">WASD/arrows walk; Space dashes; E interacts; J opens the pack; Escape closes a dialogue first, otherwise pauses. Touch: hold directions and Dash, tap Interact.</p><p class="hint">F310: set the switch underneath to X, reconnect, and press a button to expose it to the browser. Standard mapping: left stick/D-pad walk, A confirm/interact, B close, X dash, Y pack, Start pause. In menus, Up/Down moves one available row, Left/Right moves across choices, and A selects. Left/Right changes a focused setting. Typing needs a keyboard.</p><p class="hint">DirectInput fallback: A=button 1, B=2, X=0, Y=3; left stick walks. Browser mappings can vary, and physical F310 testing remains outstanding. A keyboard or touch always works as an alternative.</p></details><div class="actions"><button data-action="files">World files · Markdown</button><button data-action="export-save">Export progress</button><button data-action="import-save">Import progress</button><button data-action="new-run">New daily-seeded run</button><button class="primary" data-action="close">Back to the road</button></div>`,'settings');for(const key of ['mode','scope','avatar','pad','camera','zoom','difficulty','dialogue','idleMinutes'])$('#'+key).value=state.settings[key];/* Code by Daniel using ChatGPT — October 11, 2026 */}
function files(kind=g.editor||'scripture'){g.editor=kind;show(`<h2 id="panel-title">Two files. Your adventure.</h2><p>Scripture and adventures are separate, readable Markdown files. You can load either locally, edit it here, and download it again. Your files and replies stay in this browser.</p><div class="tabs"><button data-action="editor-tab" data-kind="scripture" class="${kind==='scripture'?'selected':''}">Scripture · ${cards.length} cards</button><button data-action="editor-tab" data-kind="adventures" class="${kind==='adventures'?'selected':''}">Adventures · ${events.length} places</button></div><label for="md-editor">${kind==='scripture'?'Scripture way-pack':'Adventure world'} Markdown</label><textarea id="md-editor" class="code" spellcheck="false">${esc(kind==='scripture'?scriptureMD:adventureMD)}</textarea><div class="actions"><button class="primary" data-action="apply-md">Validate & apply changes</button><button data-action="load-md">Load local .md</button><button data-action="export-md">Download this .md</button><button data-action="reset-files">Restore example files</button></div><p class="hint">Apply saves in this browser; it does not overwrite the original local file. Download exports the edited version. Unchanged card ids and text retain discoveries. Changed Scripture wording resets its recall record.</p><details><summary>Format & matching</summary><p class="hint">Scripture: ## reference; ### headline; card body; *Tags: fear, wisdom*; #### Metadata followed by a json code block. Adventure: ## id · title; body; #### Hint / Success / Failure / Metadata. Locations use point [x,y] or area [x,y,width,height], coordinates 0–100. Requires are flags; accept are matching words or phrases. Metadata is data, never executable JavaScript.</p><p class="hint">A keyword matches a whole word or phrase in the card body, headline, or tags. Any match wins the connection check; then half-recall unlocks the move. Tiny common words are ignored. No AI interpretation is performed. Use [chapter:verse] labels only where you have verified boundaries.</p><p class="hint">Variables: $player, $region, $card, $move, $rumor, $count. Conditions: [if flag:bridge-open]text[/if], [if item:pop-blaster]text[/if], with ! before flag/item for negation.</p></details><div class="actions"><button data-action="close">Back to the road</button></div>`,'files','YOUR LOCAL WORLD FILES');/* Code by Daniel using ChatGPT — October 11, 2026 */}
function applyDocuments(s,a){const nextCards=Road.parse(s,'scripture'),nextEvents=parseAdventures(a),next=Road.restore(state,nextCards,nextEvents,state.seed);for(const c of nextCards)next.fingerprints[c.id]=c.fingerprint;scriptureMD=s;adventureMD=a;cards=nextCards;events=nextEvents;state=next;syncRegion();state.player=Exploration.safe(state.player,terrain,bridgeOpen());Opening.reset(state.region,state.player);g.actors.clear();g.positionCache.clear();g.battle=null;g.exercise=null;persist();hud();files();toast('Validated and saved. The world now uses your Markdown.');/* Code by Daniel using ChatGPT — October 11, 2026 */}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(function revoke(){URL.revokeObjectURL(url);/* Code by Daniel using ChatGPT — October 11, 2026 */},1000);/* Code by Daniel using ChatGPT — October 11, 2026 */}
function loadFile(kind){g.fileKind=kind;$('#file-input').accept=kind==='save'?'.json':'.md,.markdown,.txt';$('#file-input').click();/* Code by Daniel using ChatGPT — October 11, 2026 */}
async function fileLoaded(event){const f=event.target.files[0];event.target.value='';if(!f)return;try{if(f.size>3000000)throw Error('Choose a file under 3 MB.');const text=await f.text();if(g.fileKind==='save'){const raw=JSON.parse(text);if(raw.state?.version!==2)throw Error('Use a Greenwood v2 progress file.');if(!window.confirm('Replace current world files and progress with this save?'))return;const s=raw.scriptureMD||scriptureMD,a=raw.adventureMD||adventureMD,nextCards=Road.parse(s,'scripture'),nextEvents=parseAdventures(a);const next=Road.restore(raw.state,nextCards,nextEvents,today);scriptureMD=s;adventureMD=a;cards=nextCards;events=nextEvents;state=next;syncRegion();state.player=Exploration.safe(state.player,terrain,bridgeOpen());Opening.reset(state.region,state.player);g.actors.clear();g.positionCache.clear();g.occlusion.clear();g.camera=Exploration.camera(state.player,viewZoom(),state.settings.camera,canvas.width/canvas.height);persist();hud();closePanel();toast('World and progress restored.');}else{if(!window.confirm('Apply this '+g.fileKind+' file to the local world?'))return;applyDocuments(g.fileKind==='scripture'?text:scriptureMD,g.fileKind==='adventures'?text:adventureMD);}}catch(error){toast(error.message);}/* Code by Daniel using ChatGPT — October 11, 2026 */}
function about(){show(`<h2 id="panel-title">Words and a world to explore</h2><p>The 84 headlines and edited card bodies come from your supplied Scripture cards. The road regions and house interiors share your discoveries and practice history. Omissions, editorial brackets, translation labels, and underlines are preserved. The riverbank home offers the first way-card; further discoveries wait along the road.</p><p>Scripture recall unlocks a fictional move. The story then supplies an ordinary means: a bridge mechanism, festival firework, warning bell, or lantern lever. Matching tags is a game rule; it is not a comprehensive interpretation of a passage or a measure of faith.</p><p>Dialogue, outcomes, and rumors come from local Markdown templates. There is no live AI or server reading your imported cards, replies, or saves. World files are stored in this browser, with readable exports.</p><p class="quote-note">${esc(NOTICES.CSB)}</p><p class="quote-note">${esc(NOTICES.LSB)} <a href="https://lsbible.org/" target="_blank" rel="noopener">LSBible.org</a> · <a href="https://316publishing.com/" target="_blank" rel="noopener">316publishing.com</a></p><p class="hint">Original generated map and sprite art. Original synthesized instrumental: Greenwood at First Light · harp-like plucks, airy flute, warm harmony, and soft air. The Elven Highroad adds the Reedbank opening, Whiteledge mountain terraces, Carverbough treehouses, walkable house interiors and an upper loft. Winding stairs have their own constrained walking surfaces and foreground rail layers. The six older regions retain their original scenery and adventures. The new slice has been checked in Chromium; physical-controller, real-phone and cross-browser testing remain outstanding. Code by Daniel using ChatGPT · October 15, 2026.</p><button class="primary" data-action="close">Back to the road</button>`,'about');/* Code by Daniel using ChatGPT — October 11, 2026 */}
